import {questionHelp,helpHint,practiceHint,helpMethod} from './question-help.mjs?v=3.9';
import {startPage,profileHub,resultActions} from './journey.mjs?v=3.7';
import {score,answerCount,validAnswer} from './instrument.mjs';
import {ROLE_INFO,ROLE_ITEMS,CONTEXT_ITEMS,PRACTICES,PRACTICE_CHOICES,INTIMACY_PAGES,INTIMACY_VERSION,validIntimate,intimateCount,roleScores,contextHighlights,temperament,intimateExport,SOURCES} from './extensions-data.mjs';
import {drawCard,saveCanvas} from './share-cards.mjs';

const fmt=n=>n.toLocaleString('cs-CZ',{minimumFractionDigits:1,maximumFractionDigits:1});
const ext=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const anchors=['Vůbec mě nevystihuje','Spíše mě nevystihuje','Částečně mě vystihuje','Spíše mě vystihuje','Velmi mě vystihuje'];
const bands={lower:'Spíše menší zájem',middle:'Střed / proměnlivé odpovědi',higher:'Spíše větší zájem',incomplete:'Chybí odpovědi'};
const notice=`<aside class="notice"><span class="notice-symbol" aria-hidden="true">i</span><div><strong>Vlastní sebereflexní dotazník · dosud nevalidovaný</strong><p>Ukazuje deklarované zájmy. Neurčuje identitu, diagnózu ani budoucí chování. <a href="#podklady-intimita">Původ otázek a odborné podklady →</a></p></div></aside>`;
const privacyNote='<p class="consent-note">Profil není souhlas s žádnou aktivitou. Přání i hranice se mohou měnit a domlouvají se v konkrétní situaci. Zájem o roli také neznamená zkušenost s ní.</p>';
export const methodNav=active=>`<nav class="wrap method-nav" aria-label="Metodiky jednotlivých modulů"><a href="#podklady" ${active==='ipip'?'aria-current="page"':''}>Osobnost IPIP-50</a><a href="#podklady-temperament" ${active==='temperament'?'aria-current="page"':''}>Temperamenty</a><a href="#podklady-intimita" ${active==='intimacy'?'aria-current="page"':''}>Intimita a role</a><a href="#podklady-porovnani" ${active==='comparison'?'aria-current="page"':''}>Porovnání profilů</a><a href="#podklady-rozbor">Osobní AI rozbor</a></nav>`;
export const shareLink='<div class="wrap share-callout"><div><span class="eyebrow">PŘEHLED DO TELEFONU</span><h2>Tvůj profil. Na jedné kartě.</h2><p>Vyber, co chceš zachytit, a stáhni přehledný obrázek PNG.</p></div><a class="button" href="#sdileni">Připravit obrázky ↗</a></div>';

export function createExtensions({show,go,getAnswers,onComplete=()=>{}}){
  const state={answers:{},step:0,started:false,showRoles:false,showPractices:false};
  const canvases=new Map();
  const count=()=>intimateCount(state.answers);
  function reset(){state.answers={};state.step=0;state.started=false;state.showRoles=false;state.showPractices=false;canvases.clear();}
  function cards(){const n=answerCount(getAnswers()),t=temperament(getAnswers());return `<div class="module-grid"><article class="module-card"><span class="module-icon" aria-hidden="true">✳</span><span class="eyebrow">01 / OSOBNOST</span><h3>Pět rozměrů osobnosti</h3><p>Extraverze, přívětivost, svědomitost, emoční stabilita a intelekt. Původní klíč IPIP-50.</p><span class="module-status">50 otázek · český překlad nevalidován</span><a class="button" href="${n?'#dotaznik':'#uvod'}">${n?`Pokračovat · ${n}/50`:'Vyplnit IPIP-50'} →</a><a class="text-link" href="#podklady">Metodika a zdroje</a></article>
  <article class="module-card temperament-card"><span class="module-icon" aria-hidden="true">◈</span><span class="eyebrow">02 / TEMPERAMENT</span><h3>Cholerik, nebo sangvinik?</h3><p>Cholerik, sangvinik, flegmatik a melancholik v historické mapě dvou rozměrů osobnosti.</p><span class="module-status">Z odpovědí IPIP-50 · ilustrativní mapa</span><a class="button secondary" href="#temperament">${t.complete?'Zobrazit mou mapu':'Prozkoumat temperamenty'} →</a><a class="text-link" href="#podklady-temperament">Metodika a zdroje</a></article>
  <article class="module-card intimacy-card"><span class="module-icon" aria-hidden="true">♡</span><span class="eyebrow">03 / INTIMITA · 18+</span><h3>Role, touha a preference</h3><p>Dominantní, submisivní, switch, roleplayer, sadistická a masochistická role i další preference.</p><span class="module-status">38 dobrovolných položek · vlastní reflexe</span><a class="button secondary" href="#intimita">${count()?`Pokračovat · ${count()}/38`:'Prozkoumat intimní profil'} →</a><a class="text-link" href="#podklady-intimita">Metodika a zdroje</a></article></div>`;}
  function catalog(){return startPage(getAnswers(),state.answers);}
  function profile(){return profileHub(getAnswers(),state.answers);}
  function intimacyIntro(){return '<div class="wrap narrow page-head compact-head"><span class="eyebrow">DOBROVOLNÝ PŘEHLED · 18+</span><h1>Co je ti blízké.<br><em>A kde máš hranice.</em></h1><p class="lead">38 položek o rolích, podmínkách pro intimitu a aktivitách. Každou můžeš přeskočit.</p></div><div class="wrap narrow intimacy-start"><p>Odpovídej za sebe podle posledních měsíců. Všechna témata předpokládají dospělé, dobrovolnost a domluvené hranice.</p><p class="small">Vlastní nevalidovaná sebereflexe. Zájem není diagnóza ani souhlas. Odpovědi se automaticky neodesílají.</p><button class="button" data-ext="start-intimacy">'+(state.started?'Pokračovat v přehledu':'Začít intimní přehled')+' →</button><details class="journey-help"><summary>Jak odpovídat a jak zůstanou data soukromá</summary><p>U výroků vyber 1–5. Střed znamená částečný souhlas; nejistotu označ samostatně. „Nevím“, „Nechci uvést“ i prázdná odpověď jsou v pořádku. Můžeš se vracet a odpovědi měnit.</p><p>Zapamatování v prohlížeči i uložení do účtu zapínáš vlastní volbou. Intimní obrázky vzniknou až po tvé volbě.</p></details><a class="text-link" href="#podklady-intimita">Zdroje, výpočet a limity →</a></div>';}

  function test(){const page=INTIMACY_PAGES[state.step];return `<div class="wrap test-wrap"><div class="test-top"><a href="#testy" class="back-link">← Všechny testy</a><span>INTIMITA · 18+</span><button class="text-button" data-action="reset" data-scope="intimacy">Smazat a začít znovu</button></div><div class="test-header"><div><span class="eyebrow">VLASTNÍ NEVALIDOVANÁ SEBEREFLEXE</span><h1>${page.title}</h1></div><div class="test-page"><strong>0${state.step+1}</strong><span>/ 8 částí</span></div></div><div class="progress-meta"><span id="intimate-progress">${count()} z 38 položek označeno</span><a href="#podklady-intimita">Podklady a limity</a></div><progress value="${count()}" max="38" aria-label="Postup intimního profilu"></progress><p class="test-hint">Všechny otázky jsou dobrovolné. ${page.kind==='rating'?'1 = vůbec mě nevystihuje · 3 = částečně · 5 = velmi mě vystihuje.':'Vyber, co tě láká nebo co je pro tebe hranicí. Odpověď není souhlas s aktivitou.'}</p>${state.step===2?'<p class="role-explanation">Sadistická a masochistická role zde znamenají výhradně konsenzuální intimní zájem dospělých. Výsledek se nevztahuje na krutost, násilí bez souhlasu ani duševní zdraví.</p>':''}
  ${helpHint}${page.kind==='practice'?practiceHint:''}<div class="question-list">${page.items.map((item,i)=>page.kind==='practice'?`<div class="practice-question"><label for="practice-${item.id}"><span class="question-num">${29+i}</span>${item.name}</label>${questionHelp('intimacy',item.id,item.name)}<select id="practice-${item.id}" name="intimate-${item.id}" data-intimate="${item.id}"><option value="">Bez odpovědi</option>${Object.entries(PRACTICE_CHOICES).map(([value,label])=>`<option value="${value}" ${state.answers[item.id]===value?'selected':''}>${label}</option>`).join('')}</select></div>`:`<fieldset class="question" id="intimate-${item.id}"><legend><span class="question-num">${state.step*4+i+1}</span>${item.text}</legend>${questionHelp('intimacy',item.id,item.text)}<div class="choices">${anchors.map((label,n)=>`<label class="choice"><input type="radio" name="intimate-${item.id}" data-intimate="${item.id}" value="${n+1}" ${state.answers[item.id]===n+1?'checked':''} aria-label="${n+1} — ${label}"><span class="choice-visual"><b>${n+1}</b><span>${label}</span></span></label>`).join('')}</div><div class="skip-choices"><label><input type="radio" name="intimate-${item.id}" data-intimate="${item.id}" value="na" ${state.answers[item.id]==='na'?'checked':''}> Nevím / netýká se mě</label><label><input type="radio" name="intimate-${item.id}" data-intimate="${item.id}" value="skip" ${state.answers[item.id]==='skip'?'checked':''}> Nechci uvést</label><button class="text-button" data-ext="clear-item" data-id="${item.id}">Vymazat</button></div></fieldset>`).join('')}</div>
  <div class="wizard-nav"><button class="button secondary" data-ext="prev" ${state.step===0?'disabled':''}>← Předchozí</button><button class="button" data-ext="next">${state.step===7?'Zobrazit můj přehled':'Další část'} →</button></div><div class="test-bottom"><a href="#intimita-vysledky">Zobrazit dosavadní odpovědi</a><span>Prázdné otázky můžeš doplnit později.</span></div></div>`;}
  function result(){if(!count())return `<div class="wrap narrow empty-state"><span class="eyebrow">INTIMNÍ PROFIL</span><h1>Tvoje vlastní<br><em>preference.</em></h1><p class="lead">Zájem o role neodvozujeme z jiných testů. Začni dobrovolným intimním přehledem.</p><a class="button" href="#intimita">Prozkoumat intimní profil →</a></div>`;const roles=roleScores(state.answers),high=roles.filter(x=>x.band==='higher'),context=contextHighlights(state.answers);return resultActions('intimacy')+`<div class="wrap page-head"><span class="eyebrow">TVŮJ INTIMNÍ PŘEHLED · 18+</span><h1>Více rolí.<br><em>Tvoje kombinace.</em></h1><p class="lead">${high.length?`Větší deklarovaný zájem se v odpovědích objevuje u oblastí: ${high.map(x=>x.name).join(', ')}.`:'Žádný jediný typ ti nepřidělujeme. Podívej se na jednotlivé odpovědi a oblasti níže.'}</p></div><div class="wrap">${notice}${privacyNote}</div>
  <section class="wrap section"><div class="section-heading"><div><span class="eyebrow">MAPA ROLÍ A DYNAMIK</span><h2>Kde se v odpovědích poznáváš.</h2></div><p>Průměr dvou vlastních položek · 1–5<br>Vyhodnoceno ${roles.filter(x=>x.complete).length} z 8 oblastí</p></div><div class="role-result-grid">${roles.map(r=>`<article class="role-result" style="--trait:${r.color}"><div class="role-result-heading"><h3>${r.name}</h3><strong>${r.complete?fmt(r.mean):'—'}<small>${r.complete?' / 5':` ${r.answered}/2`}</small></strong></div><p class="position-tag">${bands[r.band]}</p><div class="score-track ${r.complete?'':'incomplete'}"><span class="center-marker"></span>${r.complete?`<span class="score-dot" style="left:${(r.mean-1)/4*100}%"></span>`:''}</div><div class="axis-labels"><span>1</span><span>3</span><span>5</span></div><p>${r.description}</p><details><summary>Moje odpovědi a výpočet</summary>${ROLE_ITEMS.filter(x=>x.role===r.id).map(x=>`<p>${x.text}<br><strong>${answerLabel(state.answers[x.id])}</strong></p>`).join('')}<p>${r.complete?`Průměr: (${ROLE_ITEMS.filter(x=>x.role===r.id).map(x=>state.answers[x.id]).join(' + ')}) ÷ 2 = ${fmt(r.mean)}.`:'Pro číselné shrnutí jsou potřeba obě odpovědi 1–5.'} Bez norem, percentilů a diagnostických hranic.</p></details><button class="text-button" data-ext="edit" data-id="${r.id}-1">Upravit odpovědi →</button></article>`).join('')}</div><p class="fine-print">Vyšší číslo znamená větší souhlas s našimi dvěma výroky, ne větší „procento typu“. Pásma jsou pouze popisná konvence webu. <a href="#podklady-intimita">Přesná pravidla a omezení →</a></p></section>
  <section class="wrap context-results"><span class="eyebrow">MOŽNÉ SOUVISLOSTI K VLASTNÍMU OVĚŘENÍ</span><h2>Co zmiňuješ o svém kontextu.</h2><p>Tyto podněty vycházejí přímo z odpovědí 4 nebo 5. Nejde o předpověď, co uděláš nebo co ti bude určitě vyhovovat.</p><div class="context-grid">${context.length?context.map(x=>`<article class="context-card"><h3>${x.insight}</h3><p>${x.question}</p></article>`).join(''):'<p>Zatím tu nejsou výroky označené 4 nebo 5. Nižší, chybějící ani nejisté odpovědi nenahrazujeme odhadem.</p>'}</div><details class="context-all"><summary>Všech 12 odpovědí ke kontextu</summary>${CONTEXT_ITEMS.map(x=>`<div class="context-answer"><span>${x.text}</span><strong>${answerLabel(state.answers[x.id])}</strong><button class="text-button" data-ext="edit" data-id="${x.id}">Upravit</button></div>`).join('')}</details></section>
  <section class="wrap section"><span class="eyebrow">KONKRÉTNÍ PREFERENCE</span><h2>Co chceš sdělit vlastními slovy.</h2><div class="preference-result-grid">${['yes','talk','no','unsure'].map(value=>`<article class="preference-group"><h3>${PRACTICE_CHOICES[value]}</h3><ul>${PRACTICES.filter(x=>state.answers[x.id]===value).map(x=>`<li>${x.name}</li>`).join('')||'<li class="muted-text">Nic označeno</li>'}</ul></article>`).join('')}</div><p class="fine-print">Nezodpovězené a soukromé volby v těchto seznamech nezobrazujeme. „Nechci“ je tvoje nynější uvedená hranice; každá další situace vyžaduje novou domluvu.</p><button class="text-button" data-ext="edit" data-id="cuddle">Upravit přehled aktivit →</button></section>${shareLink}
  <div class="wrap final-actions"><a href="#intimita-dotaznik">Zpět k otázkám</a><a href="#podklady-intimita">Podklady tohoto profilu</a><button class="text-button" data-ext="export">Stáhnout intimní data .json</button><button class="text-button" data-action="reset" data-scope="intimacy">Smazat intimní profil</button></div>`;}
  function answerLabel(v){return validAnswer(v)?`${v} / 5 — ${anchors[v-1]}`:v==='na'?'Nevím / netýká se mě':v==='skip'?'Nechci uvést':'Bez odpovědi';}
  function temperamentPage(){const t=temperament(getAnswers());return `<div class="wrap page-head"><span class="eyebrow">HISTORICKÁ MAPA TEMPERAMENTU</span><h1>Cholerik, sangvinik…<br><em>Dva rozměry za názvem.</em></h1><p class="lead">Čtyři známá pojmenování v mapě extraverze a emoční stability. Používáme tvé odpovědi z IPIP-50; další dotazník není potřeba.</p></div><div class="wrap"><aside class="notice"><span class="notice-symbol" aria-hidden="true">i</span><div><strong>Ilustrativní převod · není validovaným testem čtyř typů</strong><p>Eysenckův diagram je historický podklad pro názvy oblastí. Převod bodů IPIP a vyznačený střed jsou vlastní konvence webu. <a href="#podklady-temperament">Přesný původ a pravidla →</a></p></div></aside></div><section class="wrap temperament-layout"><div class="temperament-paper"><div class="temperament-axis top-axis">Více rozkolísání v odpovědích</div><div class="temperament-map" role="img" aria-label="Mapa: vlevo nižší extraverze, vpravo vyšší. Nahoře nižší emoční stabilita, dole vyšší.${t.complete?` Tvoje hodnoty: extraverze ${fmt(t.extraversion)}, stabilita ${fmt(t.stability)}.`:''}"><div class="quadrant melancholic"><strong>Melancholik</strong><span>Menší extraverze<br>Více rozkolísání</span></div><div class="quadrant choleric"><strong>Cholerik</strong><span>Větší extraverze<br>Více rozkolísání</span></div><div class="quadrant phlegmatic"><strong>Flegmatik</strong><span>Menší extraverze<br>Více stability</span></div><div class="quadrant sanguine"><strong>Sangvinik</strong><span>Větší extraverze<br>Více stability</span></div><div class="middle-horizontal"></div><div class="middle-vertical"></div>${t.complete?`<div class="temperament-point" style="left:clamp(10px,${(t.extraversion-1)/4*100}%,calc(100% - 10px));top:clamp(10px,${(t.stability-1)/4*100}%,calc(100% - 10px))"><span>ty</span></div>`:''}</div><div class="temperament-axis">Více emoční stability v odpovědích</div><div class="temperament-axis axis-ends"><span>Menší extraverze ←</span><span>→ Větší extraverze</span></div><p class="fine-print">Šedý kříž = středová pásma. Mapa neměří vztek, laskavost ani duševní zdraví.</p></div><aside class="temperament-reading"><span class="eyebrow">TVOJE UMÍSTĚNÍ</span><h2>${t.complete?t.type:'Nejprve odpovědi.'}</h2>${t.complete?`<p>Extraverze <strong>${fmt(t.extraversion)} / 5</strong><br>Emoční stabilita <strong>${fmt(t.stability)} / 5</strong></p><p>${t.centre?'Alespoň jedna osa leží mezi 2,5 a 3,5. Jeden historický název by tvoje odpovědi zbytečně zjednodušoval.':`Bod spadá do oblasti tradičně označované „${t.type.toLowerCase()}“. Je to popisek oblasti v grafu, ne potvrzení neměnného typu člověka.`}</p><p>Z umístění nevyvozujeme agresivitu, morální charakter ani předpovědi vztahů. Ostatní tři škály osobnosti tento zjednodušený pohled doplňují.</p><a class="button secondary" href="#vysledky">Zobrazit celý profil IPIP-50 →</a>`:`<p>Pro umístění potřebujeme všech 10 odpovědí extraverze a 10 odpovědí emoční stability. Zatím máš ${t.answered} z těchto 20 odpovědí.</p><a class="button" href="${answerCount(getAnswers())?'#dotaznik':'#uvod'}">${answerCount(getAnswers())?'Doplnit':'Vyplnit'} IPIP-50 →</a>`}</aside></section>${t.complete?shareLink:''}<div class="wrap final-actions"><a href="#podklady-temperament">Zdroje a metodika temperamentu</a><a href="#testy">Všechny testy</a></div>`;}

  function cardSpecs(){const answers=getAnswers(),t=temperament(answers),specs=[];if(answerCount(answers))specs.push({id:'osobnost',title:'Pět rozměrů osobnosti',tag:'IPIP-50 · moje odpovědi',subtitle:'Průměry odpovědí na stupnici 1–5. Nejde o percentily.',rows:score(answers).map(x=>({label:x.name,value:x.mean,color:x.color})),note:'Český pracovní překlad: dosud nevalidovaný. Výsledek není diagnóza.',source:'Položky a klíč: ipip.ori.org · osobnosti. / verze IPIP 1.0'});
  if(t.complete)specs.push({id:'temperament',type:'temperament',title:t.type,tag:'Historická mapa temperamentu',subtitle:'Ilustrativní umístění ze dvou škál IPIP-50.',e:t.extraversion,s:t.stability,note:'Není validovaným určením typu. Střed a převod IPIP jsou konvence webu.',source:'Koncept diagramu: Eysenck (1983) · osobnosti.'});
  if(state.showRoles&&count())specs.push({id:'intimni-role',title:'Moje mapa zájmu o role',tag:'Soukromý přehled · 18+',subtitle:'Konsenzuální role dospělých · deklarovaný zájem 1–5.',rows:roleScores(state.answers).map(x=>({label:x.name,value:x.mean,color:x.color})),note:'Vlastní nevalidovaný přehled. Není diagnóza, předpověď ani souhlas.',source:'Kontext rolí: La Corte (2023) · vlastní otázky, osobnosti.'});
  if(state.showPractices&&count())specs.push({id:'intimni-preference',title:'Moje nynější preference',tag:'Soukromý přehled · 18+',subtitle:'Přímé volby; neoznačené a soukromé položky nejsou uvedeny.',rows:PRACTICES.filter(x=>Object.hasOwn(PRACTICE_CHOICES,state.answers[x.id])&&state.answers[x.id]!=='skip').map(x=>({label:x.name,detail:PRACTICE_CHOICES[state.answers[x.id]]})),note:'Vlastní sebereflexe, bez validace. Preference není souhlas s aktivitou.',source:'Souhlas se domlouvá v konkrétní situaci · osobnosti.'});return specs;}
  function sharePage(){return `<div class="wrap page-head"><span class="eyebrow">OBRÁZKY DO TELEFONU</span><h1>Tvůj přehled.<br><em>Připravený na sdílení.</em></h1><p class="lead">Každá karta má 1080 × 1350 pixelů. Stáhni PNG do telefonu, nebo si udělej screenshot náhledu. Vytvoření obrázku nikoho nekontaktuje.</p></div><div class="wrap share-controls"><p><strong>Intimní části se přidávají jen na tvou volbu.</strong> Před odesláním jinému člověku si prohlédni obsah. Uložené obrázky zůstávají v zařízení i po smazání profilu na webu.</p><label><input type="checkbox" id="share-roles" ${state.showRoles?'checked':''} ${count()?'':'disabled'}> Přidat intimní role</label><label><input type="checkbox" id="share-practices" ${state.showPractices?'checked':''} ${count()?'':'disabled'}> Přidat konkrétní intimní preference</label></div><div class="wrap share-gallery" id="share-gallery"></div><div class="wrap final-actions"><a href="#profil">Můj profil</a><a href="#testy">Vyplnit další test</a><button class="text-button" data-action="reset" data-scope="all">Smazat celý profil a začít znovu</button></div>`;}
  function paintCards(){const target=document.getElementById('share-gallery');if(!target)return;canvases.clear();const specs=cardSpecs();target.innerHTML=specs.length?'':'<div class="paper"><h2>Zatím není co zobrazit.</h2><p>Vyplň některý test. U intimního profilu navíc vyber, kterou část chceš na kartách ukázat.</p><a href="#testy">Vybrat test →</a></div>';for(const spec of specs){const canvas=drawCard(spec);canvases.set(spec.id,canvas);const card=document.createElement('article');card.className='share-preview';const img=document.createElement('img');img.src=canvas.toDataURL('image/png');img.alt=`Náhled karty: ${spec.title}`;img.width=1080;img.height=1350;const button=document.createElement('button');button.className='button secondary';button.dataset.ext='png';button.dataset.card=spec.id;button.textContent=`Stáhnout PNG · ${spec.id==='osobnost'?'osobnost':spec.id==='temperament'?'temperament':spec.id==='intimni-role'?'intimní role':'preference'}`;card.append(img,button);target.append(card);}}
  function route(hash){const routes={'#testy':[catalog,'Všechny testy','home'],'#profil':[profile,'Můj profil','results'],'#intimita':[intimacyIntro,'Intimita a role','home'],'#intimita-dotaznik':[test,'Intimní dotazník','home'],'#intimita-vysledky':[result,'Intimní profil','results'],'#temperament':[temperamentPage,'Temperament','results'],'#sdileni':[sharePage,'Obrázky do telefonu','results'],'#podklady-intimita':[intimacySources,'Podklady intimního profilu','science'],'#podklady-temperament':[temperamentSources,'Podklady temperamentů','science']};const selected=routes[hash];if(!selected)return false;show(selected[0](),selected[1],selected[2]);if(hash==='#sdileni')paintCards();return true;}
  function refresh(){route(location.hash);}
  document.addEventListener('change',event=>{const el=event.target;if(el.id==='share-roles'||el.id==='share-practices'){state[el.id==='share-roles'?'showRoles':'showPractices']=el.checked;paintCards();return;}if(!el.matches('[data-intimate]'))return;const id=el.dataset.intimate,value=/^[1-5]$/.test(el.value)?Number(el.value):el.value;if(validIntimate(id,value))state.answers[id]=value;else delete state.answers[id];const progress=document.querySelector('main progress');if(progress)progress.value=count();const label=document.getElementById('intimate-progress');if(label)label.textContent=`${count()} z 38 položek označeno`;});
  document.addEventListener('click',event=>{const button=event.target.closest('[data-ext]');if(!button)return;const action=button.dataset.ext;if(action==='start-intimacy'){state.started=true;go('#intimita-dotaznik');}if(action==='prev'&&state.step>0){state.step--;refresh();}if(action==='next'){if(state.step<7){state.step++;refresh();}else {go('#intimita-vysledky');onComplete();}}if(action==='edit'){const index=INTIMACY_PAGES.findIndex(x=>x.items.some(item=>item.id===button.dataset.id));if(index>=0){state.step=index;go('#intimita-dotaznik');}}if(action==='clear-item'){delete state.answers[button.dataset.id];document.querySelectorAll(`[data-intimate="${button.dataset.id}"]`).forEach(x=>x.checked=false);const progress=document.querySelector('main progress');if(progress)progress.value=count();document.getElementById('intimate-progress').textContent=`${count()} z 38 položek označeno`;}if(action==='png'){const canvas=canvases.get(button.dataset.card);if(canvas)saveCanvas(canvas,`osobnosti-${button.dataset.card}.png`);}if(action==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(intimateExport(state.answers),null,2)],{type:'application/json;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='osobnosti-intimni-profil.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}});
  return {route,reset,getAnswers:()=>({...state.answers}),getStep:()=>state.step,restore:(answers,step=0)=>{reset();state.answers=Object.fromEntries(Object.entries(answers||{}).filter(([id,v])=>validIntimate(id,v)));state.step=Number.isInteger(step)&&step>=0&&step<8?step:0;state.started=count()>0;},hasAnswers:()=>count()>0,cards,cardSpecs};
}

function intimacySources(){return `${methodNav('intimacy')}<div class="wrap narrow page-head"><span class="eyebrow">ZDROJE / INTIMITA A ROLE</span><h1>Výzkum v pozadí.<br><em>Vlastní otázky na webu.</em></h1><p class="lead">Podklady pomáhají vymezit témata. Samy neověřují přesnost našeho dotazníku ani nedovolují předpovídat chování jednotlivce.</p></div><article class="wrap narrow reading">${notice}<section><h2>Co přesně tady používáme</h2><p>Vlastní české znění vytvořené s pomocí AI pro tento web: 16 výroků k osmi rolím a dynamikám, 12 výroků ke kontextu a 10 přímých voleb aktivit. Nejde o převzatý BDSM Test, SIS/SES, SESII-WM ani jejich validovanou českou adaptaci. Otázky neprošly psychometrickou validací ani odbornou revizí sexuologem. Verze: <strong>${INTIMACY_VERSION}</strong>.</p><p>Profil mapuje pouze to, jak člověk popisuje své zájmy v posledních měsících. Nezjišťuje automaticky identitu, zkušenost, sexuální orientaci, diagnózu, kompatibilitu, věrnost ani souhlas.</p></section>
  <section><h2>Role nejsou jedna osa</h2><div class="source-card"><span class="source-tag">EMPIRICKÝ KONTEXT ROLÍ</span><h3>La Corte (2023; online 2022)</h3><p><cite>Classifying D/s Profiles Without Prior Assumptions: An Application of Cluster Analysis to Social Data.</cite></p><p>Studie analyzovala 236 353 internetových profilů z BDSM Testu a zkoumala více rozměrů zájmu o role. Poskytuje důvod nevynucovat jediný protiklad dominance a submise. Výběr uživatelů takového webu není reprezentativní normou pro všechny lidi.</p><p><strong>Co z ní nepřebíráme:</strong> otázky, validační výsledky pro naše znění, populační percentily ani individuální předpovědi. Samostatné položky pro switch, sadistickou či masochistickou roli jsou naší vlastní implementací.</p>${ext(SOURCES.roles,'Abstrakt původní studie · DOI 10.1080/00918369.2022.2036534')}</div></section>
  <section><h2>Kontext ovlivňuje sexuální odezvu</h2><div class="source-card"><span class="source-tag">TEORETICKÝ PODKLAD · NE SKÓROVACÍ KLÍČ</span><h3>Kinsey Institute: model dvojí kontroly</h3><p>Model Bancrofta a Janssena rozlišuje podněty podporující sexuální odezvu a procesy, které ji tlumí. Nejde jen o dva konce jedné osy; citlivost se může lišit mezi lidmi i situacemi. To je podkladem pro oddělené otázky na příjemné podmínky, stres a rušení.</p><p>Naše otázky nejsou měřením validovanými inventáři tohoto modelu a nepočítáme z nich celkové skóre „plyn versus brzda“.</p>${ext(SOURCES.dual,'Vysvětlení modelu v Kinsey Institute')}</div><div class="source-card"><span class="source-tag">KOMUNIKACE A PARTNERSKÝ KONTEXT</span><h3>MacNeil & Byers (2009)</h3><p><cite>Role of sexual self-disclosure in the sexual satisfaction of long-term heterosexual couples.</cite></p><p>Studie 104 heterosexuálních párů v dlouhodobých vztazích zkoumala souvislosti sdělování sexuálních preferencí se spokojeností. Zdůvodňuje zařazení tématu komunikace. Vztah ve výzkumu není zárukou výsledku pro jednotlivce ani důkazem platnosti našich otázek.</p>${ext(SOURCES.communication,'Abstrakt původní studie · DOI 10.1080/00224490802398399')}</div></section>
  <section><h2>Preference není diagnóza ani souhlas</h2><div class="source-card"><h3>WHO: ICD-11, klinické popisy (2024)</h3><p>U donucujícího sexuálního sadismu se rozlišuje chování vůči nesouhlasící osobě od konsenzuálního sadismu a masochismu. Samotný zájem o konsenzuální role není diagnóza. Zdravotní posouzení zahrnuje další okolnosti, například výrazné strádání nebo závažné riziko újmy. Tento dotazník je neposuzuje.</p>${ext(SOURCES.who,'WHO, Clinical descriptions and diagnostic requirements · s. 581 a 588–589')}</div><div class="source-card"><h3>WHO: vymezení sexuálního zdraví</h3><p>Pracovní rámec zdůrazňuje respekt, dobrovolnost a nepřítomnost nátlaku a násilí. Odpověď „láká mě“ nebo vysoký průměr nikdy není souhlasem s konkrétní aktivitou.</p>${ext(SOURCES.sexualHealth,'Pracovní definice a souvislosti')}</div></section>
  <section><h2>Otevřená pravidla vyhodnocení</h2><p>Každá role má dva přímo formulované výroky. Souhlas hodnotíš 1–5. Až při dvou číselných odpovědích zobrazíme jejich aritmetický průměr. „Nevím / netýká se mě“, „Nechci uvést“ a prázdná odpověď nejsou číslo a nic za ně nedoplňujeme.</p><p>Popisy průměrů ≤ 2,5, mezi 2,5 a 3,5 a ≥ 3,5 jsou vlastní konvence pro menší, střední a větší deklarovaný zájem. Nejsou to normy, klinické prahy, procenta typu ani ověřené klasifikace. Dvě podobné otázky navíc samy o sobě nedokládají spolehlivost měření.</p><p>Kontextové odpovědi nesčítáme. Souhrn pouze připomene výroky označené 4 nebo 5 a přidá otázku k zamyšlení. Preference aktivit se zobrazují přesně podle vybrané možnosti. Všechna interpretační shrnutí a obrázkové karty jsou vlastní a nevalidované. Odpovědi z osobnostního testu se do intimního profilu nepřenášejí.</p></section><section><h2>Jaké „předpovědi“ jsou možné?</h2><p>Tento web žádný predikční model nemá. „Možné souvislosti“ znamenají pouze náměty vycházející z toho, co sám/sama uvedeš. Ze zájmu nelze vyvozovat, jak budeš jednat, co budeš chtít s konkrétním člověkem nebo jak dopadne vztah.</p></section><div class="bottom-callout"><a class="button" href="#intimita">Přejít k intimnímu přehledu →</a></div>${helpMethod('intimacy')}</article>`;}

function temperamentSources(){return `${methodNav('temperament')}<div class="wrap narrow page-head"><span class="eyebrow">ZDROJE / TEMPERAMENTY</span><h1>Známé názvy.<br><em>Přesně popsaný převod.</em></h1><p class="lead">Cholerik, sangvinik, flegmatik a melancholik jako historická orientační mapa. Není to samostatně validovaný test čtyř druhů lidí.</p></div><article class="wrap narrow reading"><section><h2>Odkud se bere diagram?</h2><div class="source-card"><h3>H. J. Eysenck (1983)</h3><p><cite>Psychophysiology and Personality: Extraversion, Neuroticism and Psychoticism.</cite> Autorův diagram na tištěné straně 14 (2. strana PDF) propojuje historické názvy s extraverzí a emoční nestabilitou či stabilitou. Zde kreslíme vlastní ilustraci tohoto uspořádání.</p>${ext(SOURCES.eysenck,'Původní autorský text a diagram (PDF)')}</div><p>Vpravo je větší extraverze: nahoře oblast cholerika, dole sangvinika. Vlevo je menší extraverze: nahoře melancholik, dole flegmatik. Vertikální směr na našem webu roste dolů k větší emoční stabilitě.</p></section><section><h2>Co je na tomto webu vlastní?</h2><p>Do diagramu vkládáme průměry dvou škál našeho českého pracovního překladu IPIP-50. Používáme 10 položek extraverze a 10 položek emoční stability v původním klíči IPIP. Eysenckův text tento převod IPIP na čtyři názvy nevaliduje. Neadministrovali jsme EPI ani EPQ.</p><p>Bod má souřadnice x = (extraverze − 1) ÷ 4 a y = (stabilita − 1) ÷ 4. Pro pojmenování rozlišujeme nižší hodnoty ≤ 2,5 a vyšší ≥ 3,5. Pokud je alespoň jedna osa mezi 2,5 a 3,5, zobrazujeme smíšenou / středovou oblast. Šedý kříž v mapě odpovídá tomuto středovému pásmu. Hranice jsou jen naše zobrazovací konvence, ne populační normy.</p><p>Chybí-li kterákoli z 20 potřebných odpovědí, bod ani název oblasti nevytvoříme. Ostatní škály Big Five neovlivňují umístění. <a href="#podklady">Znění, klíč a omezení IPIP-50 →</a></p></section><section><h2>Co z umístění neplyne</h2><p>Neuvádíme procenta cholerika nebo směs čtyř „pravých typů“. Mapa neprokazuje výbušnost, agresivitu, pasivitu, kvalitu charakteru ani duševní poruchu. Například označení melancholik samo o sobě neznamená depresi. Pro přesnější popis si prohlédni všech pět osobnostních škál a jednotlivé odpovědi.</p><p>Podklad IPIP i tento převod mají zde výslovně popsaná omezení: vlastní český překlad nemá psychometrické ověření a mapa není diagnostický nástroj. Verze převodu: temperament-map-1.0.0.</p></section><div class="bottom-callout"><a class="button" href="#temperament">Otevřít mapu temperamentu →</a></div></article>`;}
